import React from 'react';
import { AlertCircle, CheckCircle2 } from 'lucide-react';

const ScheduleTab = ({ onReportClick }) => {
  const schedule = [
    { id: 101, time: "08:00", area: "ZONE_A", task: "Routine Pick", status: "Done" },
    { id: 102, time: "10:30", area: "ZONE_C", task: "Citizen Report", status: "Alert", hasReport: true },
    { id: 103, time: "14:00", area: "ZONE_B", task: "Bulk Disposal", status: "Pending" },
  ];

  return (
    <div className="animate-slide-up space-y-4">
      <h2 className="text-[10px] font-black text-[#47510B]/40 uppercase tracking-[0.3em] mb-6">Daily_Timeline</h2>
      {schedule.map((item) => (
        <div key={item.id} className={`p-5 rounded-[35px] border-2 border-[#47510B] shadow-[6px_6px_0_0_#47510B] flex justify-between items-center transition-all ${item.hasReport ? 'bg-[#FFB6A9]' : 'bg-white'}`}>
          <div>
            <span className="text-[10px] font-black opacity-40 italic">{item.time} // {item.area}</span>
            <h3 className="text-xl font-black text-[#47510B] uppercase italic">{item.task}</h3>
          </div>
          {item.hasReport ? (
            <button onClick={onReportClick} className="bg-[#AB1717] text-white p-3 rounded-2xl animate-bounce shadow-lg">
              <AlertCircle size={20} />
            </button>
          ) : (
            <div className="text-[#47510B]/20"><CheckCircle2 size={24} /></div>
          )}
        </div>
      ))}
    </div>
  );
};

export default ScheduleTab;
